import json,re,collections,html,xml.etree.ElementTree as ET
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text())
assert len(s)==len(a)==24
assert len({x['source_id'] for x in a})==24
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
def plain(x):
 x=re.sub(r'<(?:p\\b["'^>]*|br'"\\s*/?)>', '\\n', x)
 return html.unescape(re.sub(r'<["'^>]*>'"', '', x))
def numbers(x): return collections.Counter(re.findall(r'\\d+(?:[.,]\\d+)?',plain(x)))
def refs(x): return collections.Counter(re.findall(r'\\b([LRD])\\.?\\s*(\\d[\\d-]*)',plain(x)))
def subdivisions(x): return re.findall(r'(?m)"'^'"\\s*(III bis\\.|[IVX]+\\.|[a-z](?: bis)?\\)|\\d+°)',plain(x))
def cells(x):
 root=ET.fromstring('<root>'+x+'</root>')
 return [[[' '.join(''.join(c.itertext()).split()) for c in row] for row in t.findall('.//tr')] for t in root.findall('.//table')]
for source,out in zip(s,a):
 assert set(out)=={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
 assert all(source[k]==out[k] for k in ('code_id','source_id','source_sha256','number'))
 assert out['status']=='rewrite_draft'
 assert all(isinstance(out[k],str) and out[k].strip() for k in ('proposed_xml','reason','review_notes'))
 assert plain(source['source_xml']).strip()"'!=plain(out['"'proposed_xml']).strip()
 assert numbers(source['source_xml'])==numbers(out['proposed_xml']),source['number']
 assert refs(source['source_xml'])==refs(out['proposed_xml']),source['number']
 assert subdivisions(source['source_xml'])==subdivisions(out['proposed_xml']),(source['number'],subdivisions(source['source_xml']),subdivisions(out['proposed_xml']))
 assert cells(source['source_xml'])==cells(out['proposed_xml']),source['number']
 root=ET.fromstring('<root>'+out['proposed_xml']+'</root>')
 assert root.text is None or not root.text.strip()
 for e in root.iter():
  if e.tag=='root':continue
  assert e.tag in allowed
  assert all(k in ('rowspan','colspan') and re.fullmatch('[0-9]+',v) for k,v in e.attrib.items())
 assert not any(t in out['proposed_xml'] for t in ['"'```'"','http://','https://','texte inchangé'])
 print(source['number'],'OK')
print('VALIDATION: 24 articles, identifiants exacts, chiffres et renvois conservés, subdivisions conservées, tableau intégral, XML autorisé.')
for i in [0,1,4,5,9,11,13,16]:
 print('\\nDERNIER CONTROLE',a[i]['number'])
 if i in [1,4,5,16]:
  root=ET.fromstring('<root>'+a[i]['proposed_xml']+'</root>')
  targets={1:[3],4:[0,5],5:[2,4,9],16:[0,1]}[i]
  for j in targets:print(ET.tostring(root.findall('p')[j],encoding='unicode'))
 else: print(a[i]['proposed_xml'])
PY"

